Post-verification feedback on your previous Rust:
Conformance violation: no model statement matches mutex_lock on "main::m" (thread t1) (event 0).
Fix the Rust; do not change the design.

Output only the complete Rust program in one ```rust fence.

content:
```rust
use std::sync::{mpsc, Arc, Mutex};
use std::thread;

fn main() {
    let (tx, rx) = mpsc::sync_channel::<i32>(1);
    let m = Arc::new(Mutex::new(()));

    let m_sender = Arc::clone(&m);
    let m_receiver = Arc::clone(&m);

    let sender = thread::spawn(move || {
        {
            let _guard = m_sender.lock().unwrap();
        }
        tx.send(1).unwrap();
        tx.send(2).unwrap();
    });

    let receiver = thread::spawn(move || {
        {
            let _guard = m_receiver.lock().unwrap();
        }
        let _x = rx.recv().unwrap();
        let _y = rx.recv().unwrap();
    });

    sender.join().unwrap();
    receiver.join().unwrap();

    println!("DONE done=1");
}
```
